from math import isqrt

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, isqrt(n) + 1, 2):
        if n % i == 0:
            return False
    return True

def prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def is_resonant_frequency(freq):
    factors = prime_factors(freq)
    if len(factors) != 2 or factors[0] == factors[1]:
        return False
    p, q = sorted(factors)
    return freq % (p + q) == p

