    hashes = list(map(hash_permission, validated_nodes))
    max_hash = max(hashes) if hashes else 0
    min_hash = min(hashes) if hashes else 0
    return reduce(lambda x, y: x ^ y, hashes, 0) if max_hash > min_hash else 0

