    tokens = tokenize_config(config)
    decision_tree = build_decision_tree(tokens)
    route_queue = deque(["192.168.1.1:80", "192.168.1.2:22", "10.0.0.5:443", "172.16.0.1:8080"])
    matched_routes = 0

